         b0*p[0].y+b1*p[1].y+b2*p[2].y+b3*p[3].y};
    return r;
}
int main(void){
    // unit square patch, all edges straight
    P top[]={{0,0},{1.f/3,0},{2.f/3,0},{1,0}};
    P right[]={{1,0},{1,1.f/3},{1,2.f/3},{1,1}};
    P bottom[]={{0,1},{1.f/3,1},{2.f/3,1},{1,1}}; // p0=left-bottom, p3=right-bottom
