int main(int argc,char**argv){
    plutosvg_document_t* doc=plutosvg_document_load_from_file(argv[1],-1,-1);
    plutovg_surface_t*s=plutosvg_document_render_to_surface(doc,NULL,256,256,NULL,NULL,NULL);
    unsigned char*d=plutovg_surface_get_data(s);
    int st=plutovg_surface_get_stride(s);
    long trans=0,tot=0; double sr[4][4]={0}; long cnt[4][4]={0};
    for(int y=0;y<256;y++)for(int x=0;x<256;x++){
        unsigned char*p=d+y*st+x*4; // ARGB premul
        int a=p[0]; tot++;
        if(a==0)trans++;
        int qx=x/128,qy=y/128;
        sr[qy][qx]+=a? (p[1]+p[2]+p[3])/3.0:0;
        if(a)cnt[qy][qx]++;
    }
    printf("%s transparent=%.1f%%\n",argv[1],100.0*trans/tot);
    for(int qy=0;qy<2;qy++)for(int qx=0;qx<2;qx++)
        printf(" quadrant %d,%d meanRGB=%.0f filled=%.1f%%\n",qx,qy,sr[qy][qx]/(cnt[qy][qx]?cnt[qy][qx]:1),100.0*cnt[qy][qx]/(128*128));
    return 0;
}
