    P e2[]={{128,128},{85.3f,128},{42.7f,128},{0,128}};
    P e3[]={{0,128},{0,85.3f},{0,42.7f},{0,0}};
    for(int iy=0;iy<=4;iy++)for(int ix=0;ix<=4;ix++){
